@media(max-width:950px){
 .workspace-grid>.right-stack{grid-template-columns:1fr 1fr}
 .workspace-grid>.right-stack .warning-panel{grid-column:1/-1}
}
@media(max-width:780px){
 .theme-classic-fantasy .workspace-grid .input-devices{flex-direction:column}
 .theme-classic-fantasy .workspace-grid .input-devices>.canvas-scroll{flex:0 0 auto;width:100%;max-width:100%}
 .theme-classic-fantasy .workspace-grid .input-devices>.mouse-side{flex:0 0 auto;width:100%;max-width:none;border:0;border-top:1px solid #88643a;padding:10px 0 0}
 .theme-classic-fantasy .workspace-grid .input-devices .mouse-keys{grid-template-columns:repeat(4,minmax(0,1fr))}
 .workspace-grid>.right-stack{display:flex;flex-direction:column}
 .workspace-grid>.right-stack .warning-panel{grid-column:auto}
}
@media(max-width:570px){
 .workspace-grid>.action-library-panel .ability-list{grid-template-columns:repeat(2,minmax(0,1fr))}
 .workspace-grid>.action-library-panel .general-list{grid-template-columns:1fr}
}
